+      errorElement.textContent = 'Please select at least one answer.';
+      
+      // Focus first checkbox
+      checkboxes[0].focus();
+    } else {
+      errorElement.hidden = true;
+      errorElement.textContent = '';
+    }
+  });
+  
+  return allValid;
+}
+
+function clearErrors() {
+  const errors = form.querySelectorAll('p[id*="error"]');
+  errors.forEach((error) => {
+    error.hidden = true;
+    error.textContent = '';
+  });
+}
+
+function calculateScore() {
+  let correctCount = 0;
+  const totalQuestions = Object.keys(CORRECT_ANSWERS).length;
+  
+  Object.entries(CORRECT_ANSWERS).forEach(([questionId, correctAnswers]) => {
+    const selectedAnswers = Array.from(
+      form.querySelectorAll(`input[name="${questionId}"]:checked`)
+    ).map(cb => cb.value);
+    
+    // Check if selected answers exactly match correct answers
+    const isCorrect = 
+      selectedAnswers.length === correctAnswers.length &&
+      selectedAnswers.every(answer => correctAnswers.includes(answer));
+    
+    if (isCorrect) {
+      correctCount++;
+    }
+  });
+  
+  return { correct: correctCount, total: totalQuestions };
+}
+
+function displayResults(score) {
+  const percentage = Math.round((score.correct / score.total) * 100);
+  
+  resultMessage.hidden = false;
+  
+  if (score.correct === score.total) {
+    resultMessage.className = 'success';
+    resultMessage.textContent = `Perfect! You got all ${score.total} questions correct.`;
+  } else if (score.correct >= score.total / 2) {
+    resultMessage.className = 'success';
+    resultMessage.textContent = `Great job! You got ${score.correct} out of ${score.total} correct (${percentage}%).`;
+  } else {
+    resultMessage.className = 'error';
+    resultMessage.textContent = `You got ${score.correct} out of ${score.total} correct (${percentage}%). Try again!`;
+  }
+  
+  // Scroll to results
+  resultMessage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
+}
+
')

